css:
/* The handoff sets this band on --color-ink (#242424), the text colour, not
   the near-black the header and footer use. */
[data-bz-node="loc-cta-band"]{background:#242424;padding-top:90px;padding-bottom:90px;text-align:center;}
[data-bz-node="loc-cta-band"] .bz-block{padding-block:0;}
.bz-block[data-bz-node="loc-cta-heading"] p.bz-eyebrow{font:700 11px/1 var(--font-body);letter-spacing:.16em;color:#A0A0A0;margin:0 0 18px;}
[data-bz-node="loc-cta-heading"] h2{font:800 34px/1.7 var(--font-heading);letter-spacing:normal;color:#fff;margin:0 0 18px;}
[data-bz-node="loc-cta-body"]{margin-bottom:30px;}
[data-bz-node="loc-cta-body"] .bz-text{max-width:620px;margin-inline:auto;}
[data-bz-node="loc-cta-body"] p{font-size:15px;line-height:1.7;color:#C7C1B4;margin:0;}
[data-bz-node="loc-cta-buttons"] .bz-btns{justify-content:center;gap:14px;}
[data-bz-node="loc-cta-buttons"] .bz-btn{min-height:48px;padding:0 26px;font:700 14px/1.7 var(--font-body);}
[data-bz-node="loc-cta-buttons"] .bz-btn--secondary{background:none;border:1px solid #fff;color:#fff;}
[data-bz-node="loc-cta-buttons"] .bz-btn--secondary:hover{background:#fff;color:#141414;}
@media (max-width:640px){[data-bz-node="loc-cta-band"]{padding-top:56px;padding-bottom:56px;}[data-bz-node="loc-cta-heading"] h2{font-size:26px;}}
